    private void addGame(LinearLayout parent,String name,String pkg){TextView g=text("🎮   "+name+"\n      "+pkg,14,Color.WHITE,true);g.setPadding(dp(14),dp(16),dp(14),dp(16));g.setBackground(shape(Color.rgb(35,20,48),Color.rgb(75,40,95),14));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.topMargin=dp(10);parent.addView(g,p);g.setOnClickListener(v->{selectedGame=name;selectedPkg=pkg;showModules();});}
    private void showModules(){modules.clear();LinearLayout panel=column();panel.setPadding(dp(20),dp(16),dp(20),dp(16));String[] ids={"aim","esp","chams"},names={"AIMBOT","ESP","CHAMS GOD"},descs={"Hỗ trợ ngắm mục tiêu","Hiển thị thông tin đối tượng","Tô màu nhân vật địch"};for(int i=0;i<ids.length;i++){CheckBox cb=new CheckBox(this);cb.setText(names[i]+"\n"+descs[i]);cb.setTextColor(Color.WHITE);cb.setTextSize(14);cb.setButtonTintList(android.content.res.ColorStateList.valueOf(accent));panel.addView(cb);modules.put(ids[i],cb);}new AlertDialog.Builder(this).setTitle("MODULE • "+selectedGame).setView(panel).setNegativeButton("ĐÓNG",null).setPositiveButton("KÍCH HOẠT PATCH",(d,w)->runPatch()).show();}
    private void runPatch(){if(!shizukuGranted){alert("CHƯA KẾT NỐI","Vui lòng kết nối Shizuku trước khi patch game.");return;}ArrayList<String> enabled=new ArrayList<>();for(String k:modules.keySet())if(modules.get(k).isChecked())enabled.add(k);if(enabled.isEmpty()){alert("CHƯA CHỌN CHỨC NĂNG","Vui lòng bật ít nhất 1 chức năng.");return;}
        ProgressDialog progress=new ProgressDialog(this);progress.setTitle("ĐANG PATCH...");progress.setMessage("Đang chuẩn bị...");progress.setProgressStyle(ProgressDialog.STYLE_HORIZONTAL);progress.setMax(100);progress.setCancelable(false);progress.show();new Thread(()->{for(int i=0;i<=100;i+=5){int n=i;runOnUiThread(()->{progress.setProgress(n);progress.setMessage(n<35?"Đang chuẩn bị...":n<65?"Đang patch memory...":n<95?"Đang inject module...":"Hoàn tất...");});try{Thread.sleep(180);}catch(Exception ignored){}}String msg;try{if(!Shizuku.pingBinder()||Shizuku.checkSelfPermission()!=PackageManager.PERMISSION_GRANTED)throw new SecurityException("Shizuku permission unavailable");Process p=Shizuku.newProcess(new String[]{"sh","-c","am force-stop "+selectedPkg+" ; monkey -p "+selectedPkg+" 1"},null,null);int code=p.waitFor();msg=code==0?"Đã gửi lệnh khởi động lại "+selectedGame+".\nModule đã chọn: "+enabled:"Lệnh hệ thống trả về mã "+code;}catch(Exception e){msg="Không thể chạy lệnh Shizuku: "+e.getMessage();}String result=msg;runOnUiThread(()->{progress.dismiss();alert("KẾT QUẢ",result+"\n\nLưu ý: mã nguồn gốc chỉ mô phỏng các module AIM/ESP/CHAMS; không có thuật toán can thiệp game thực tế.");});}).start(); }

    private void connectShizuku(){try{if(!Shizuku.pingBinder()){alert("SHIZUKU CHƯA CHẠY","Mở Shizuku và khởi động dịch vụ qua Wireless Debugging hoặc Root.");return;}if(Shizuku.checkSelfPermission()==PackageManager.PERMISSION_GRANTED){shizukuGranted=true;updateShizukuUI();toast("Đã kết nối Shizuku");}else Shizuku.requestPermission(REQUEST_CODE);}catch(Exception e){alert("LỖI SHIZUKU",e.getMessage());}}
    private void updateShizukuUI(){runOnUiThread(()->{if(shizukuStatus==null)return;boolean running=false;try{running=Shizuku.pingBinder();shizukuGranted=running&&Shizuku.checkSelfPermission()==PackageManager.PERMISSION_GRANTED;}catch(Exception ignored){}shizukuStatus.setText(shizukuGranted?"✓ Đã kết nối Shizuku":running?"Shizuku đang chạy • Chưa cấp quyền":"Shizuku chưa chạy / chưa cài đặt");shizukuStatus.setTextColor(shizukuGranted?GREEN:MUTED);});}
    private void startMonitor(){handler.removeCallbacks(monitor);handler.postDelayed(monitor,30000);}private final Runnable monitor=()->{String k=prefs.getString("key","");if(!k.isEmpty())verify(k,true);handler.postDelayed(monitor,30000);};
